window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"pl-storm":{src:"act:storm",route:"#/atlas/honey/storm",cta:"Open the Storm of Elements",title:"Act IV · The Storm of Elements",body:"10 stops on this road, from “anti- / hyper- / hypo- (against / over / under)” to “Medical Suffixes: -itis / -osis / -ectomy / -plasty / -scope / -meter”."},"li-u45":{src:"concept:34:concept",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under)",body:"Greek anti- = against, hyper- = over/excessive, hypo- = under/insufficient. In medicine, knowing the prefix IS knowing the diagnosis. In literature, hyperbole and hypocrisy are built from this same trio."},"lc-u45-0":{src:"concept:34:cards:0",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under) · anti- = Against",body:"Antipathy (anti- + pathos) = feeling against = deep dislike. Antithesis = placed against = direct opposite. Antidote (anti- + didonai = give) = given against a poison. Anticlimactic = against the expected climax = disappointingly flat after a buildup."},"lc-u45-1":{src:"concept:34:cards:1",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under) · hyper- = Over/Excessive",body:"Hyperbole (hyper- + ballein = throw) = throwing over = deliberate exaggeration for effect. Hypertrophy (hyper- + trophe = nourishment) = excessive growth. Hyperopia (hyper- + ops = eye) = over-seeing = farsightedness. Hypercritical = excessively critical. Hyperventilate = breathe excessively fast."},"lc-u45-2":{src:"concept:34:cards:2",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under) · hypo- = Under/Insufficient",body:"Hypothesis (hypo- + thesis = placing) = placed under consideration. Hypocrisy (hypo- + krinein = judge) = judging from under a mask = pretending to have values you lack. Hypochondria (hypo- + khondros = cartilage) = below the ribs = once thought the seat of anxiety."},"lc-u45-3":{src:"concept:34:cards:3",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under) · Medical hyper-/hypo- Pairs",body:"Hypertension = blood pressure TOO HIGH. Hypotension = TOO LOW. Hyperthyroid = thyroid overactive. Hypothyroid = underactive. Hyperglycemia = too much blood sugar. Hypoglycemia = too little. Knowing prefix = knowing diagnosis. One pattern unlocks twelve medical terms."},"lc-u45-4":{src:"concept:34:cards:4",route:"#/stop/u45",cta:"Open this stop",title:"anti- / hyper- / hypo- (against / over / under) · Spelling Traps",body:"Hyperbole ends in -le and the e is PRONOUNCED: hy-PER-buh-lee. Hypocrisy = H-Y-P-O-C-R-I-S-Y (not -acy). Hypothesis → plural hypotheses (Greek -es plural). Antipathy = A-N-T-I-P-A-T-H-Y (-thy not -thee). The -th- = /th/ from Greek theta."},"uq-u45-0":{src:"unit:u45:qs:0",route:"#/stop/u45",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “anti- / hyper- / hypo- (against / over / under)”?",opts:["Greek anti- = against, hyper- = over/excessive, hypo- = under/insufficient.",'The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of."],after:"From “anti- / hyper- / hypo- (against / over / under)”."}},"uq-u45-3":{src:"unit:u45:qs:3",route:"#/stop/u45",cta:"Open this stop",title:"Whose hook?",play:{q:"“ANTI-PATHy — you are on the ANTI PATH to liking someone” — which word is this hook about?",opts:["antipathy","antithesis","antidote","anticlimactic"],after:"From “anti- / hyper- / hypo- (against / over / under)”."}},"wx-antipathy":{src:"concept:34:words:0:ex",route:"#/word/antipathy",cta:"Open the word card",title:"In a sentence · antipathy",body:"The two rival teams developed a deep antipathy toward each other after years of intense competition.",clip:1},"wh-antipathy":{src:"concept:34:words:0:hook",route:"#/word/antipathy",cta:"Open the word card",title:"Remember it · antipathy",body:"ANTI-PATHy — you are on the ANTI PATH to liking someone"},"wo-antipathy":{src:"lore:antipathy:0",route:"#/word/antipathy",cta:"Open the word card",title:"Where it comes from · antipathy",body:"Greek 'antipatheia' = opposite feeling, from 'anti-' = against + 'pathos' = feeling"},"wd-antithesis":{src:"concept:34:words:1:def",route:"#/word/antithesis",cta:"Open the word card",title:"antithesis",roman:"a-NTIH-thuh-suhs",body:"exact opposite",clip:1},"wx-antithesis":{src:"concept:34:words:1:ex",route:"#/word/antithesis",cta:"Open the word card",title:"In a sentence · antithesis",body:"Wearing pajamas to school would be the antithesis of the dress code the principal had just announced.",clip:1},"wh-antithesis":{src:"concept:34:words:1:hook",route:"#/word/antithesis",cta:"Open the word card",title:"Remember it · antithesis",body:"ANTI + THESIS — the opposite of your thesis"},"wo-antithesis":{src:"lore:antithesis:0",route:"#/word/antithesis",cta:"Open the word card",title:"Where it comes from · antithesis",body:"Greek anti = against + tithenai = to place"},"wd-antidote":{src:"concept:34:words:2:def",route:"#/word/antidote",cta:"Open the word card",title:"antidote",roman:"A-ntih-doht",body:"a remedy that stops or controls the effects of a poison",clip:1},"wx-antidote":{src:"concept:34:words:2:ex",route:"#/word/antidote",cta:"Open the word card",title:"In a sentence · antidote",body:"The doctor administered the antidote quickly after the child accidentally swallowed a toxic substance.",clip:1},"wh-antidote":{src:"concept:34:words:2:hook",route:"#/word/antidote",cta:"Open the word card",title:"Remember it · antidote",body:"ANTIDOTE: the DOT in the middle is your cure — find the DOT and you've found the remedy."},"wo-antidote":{src:"lore:antidote:0",route:"#/word/antidote",cta:"Open the word card",title:"Where it comes from · antidote",body:"Greek antidoton = given against (anti=against + didonai=give)"},"wd-anticlimactic":{src:"concept:34:words:3:def",route:"#/word/anticlimactic",cta:"Open the word card",title:"anticlimactic",roman:"a-ntee-kleye-MA-ktihk",body:"of or relating to a sudden change from an impressive to a ludicrous style",clip:1},"wx-anticlimactic":{src:"concept:34:words:3:ex",route:"#/word/anticlimactic",cta:"Open the word card",title:"In a sentence · anticlimactic",body:"everything after the discovery of the murderer was anticlimactic",clip:1},"wh-anticlimactic":{src:"concept:34:words:3:hook",route:"#/word/anticlimactic",cta:"Open the word card",title:"Remember it · anticlimactic",body:"antiCLIMACtIC: spot CLIMAC in the middle — it climbs up then crashes down, just like the meaning."},"wo-anticlimactic":{src:"lore:anticlimactic:0",route:"#/word/anticlimactic",cta:"Open the word card",title:"Where it comes from · anticlimactic",body:"Greek klimax = ladder, climax; anti = against"},"wd-antipodal":{src:"concept:34:words:4:def",route:"#/word/antipodal",cta:"Open the word card",title:"antipodal",roman:"a-NTIH-puh-duhl",body:"on the exact opposite side of the earth from somewhere else",clip:1},"wx-antipodal":{src:"concept:34:words:4:ex",route:"#/word/antipodal",cta:"Open the word card",title:"In a sentence · antipodal",body:"New Zealand is almost antipodal to Spain, so their seasons are completely reversed.",clip:1},"wh-antipodal":{src:"concept:34:words:4:hook",route:"#/word/antipodal",cta:"Open the word card",title:"Remember it · antipodal",body:"ANTIPODal — their PODS (feet) point opposite to yours through the earth."},"wo-antipodal":{src:"lore:antipodal:0",route:"#/word/antipodal",cta:"Open the word card",title:"Where it comes from · antipodal",body:"Greek antipodes: anti (against) + pous/podos = foot"},"wd-hyperbole":{src:"concept:34:words:5:def",route:"#/word/hyperbole",cta:"Open the word card",title:"hyperbole",roman:"h-ay-p-UR-b-uh-l-ee",body:"obvious exaggeration",clip:1},"wx-hyperbole":{src:"concept:34:words:5:ex",route:"#/word/hyperbole",cta:"Open the word card",title:"In a sentence · hyperbole",body:"Saying you have a million hours of homework is a classic hyperbole that most students use every week.",clip:1},"wh-hyperbole":{src:"concept:34:words:5:hook",route:"#/word/hyperbole",cta:"Open the word card",title:"Remember it · hyperbole",body:"HyperbolE ends in a silent E — that silent E is itself an exaggeration, throwing sound beyond the word."},"wo-hyperbole":{src:"lore:hyperbole:0",route:"#/word/hyperbole",cta:"Open the word card",title:"Where it comes from · hyperbole",body:"Greek hyper=beyond + ballein=to throw"},"wd-hypertrophy":{src:"concept:34:words:6:def",route:"#/word/hypertrophy",cta:"Open the word card",title:"hypertrophy",roman:"HEYE-per-troh-fee",body:"abnormal enlargement of a body part or organ",clip:1},"wx-hypertrophy":{src:"concept:34:words:6:ex",route:"#/word/hypertrophy",cta:"Open the word card",title:"In a sentence · hypertrophy",body:"The cardiologist warned that the patient's heart hypertrophy, caused by years of untreated high blood pressure, needed immediate treatment.",clip:1},"wh-hypertrophy":{src:"concept:34:words:6:hook",route:"#/word/hypertrophy",cta:"Open the word card",title:"Remember it · hypertrophy",body:"HYPER(too much)+TROPHY = a body part that 'wins' too much growth"},"wo-hypertrophy":{src:"lore:hypertrophy:0",route:"#/word/hypertrophy",cta:"Open the word card",title:"Where it comes from · hypertrophy",body:"Greek hyper = over + trophe = nourishment"},"wd-hyperopia":{src:"concept:34:words:7:def",route:"#/word/hyperopia",cta:"Open the word card",title:"hyperopia",roman:"heye-per-OH-pee-ah",body:"abnormal condition in which vision for distant objects is better than for near objects",clip:1},"wx-hyperopia":{src:"concept:34:words:7:ex",route:"#/word/hyperopia",cta:"Open the word card",title:"In a sentence · hyperopia",body:"Her optometrist diagnosed her with hyperopia, explaining why she could read the distant scoreboard but not her textbook.",clip:1},"wh-hyperopia":{src:"concept:34:words:7:hook",route:"#/word/hyperopia",cta:"Open the word card",title:"Remember it · hyperopia",body:"HyperOPIA — the OP in the middle are your OPtics seeing too far BEYOND; end simply with -IA."},"wo-hyperopia":{src:"lore:hyperopia:0",route:"#/word/hyperopia",cta:"Open the word card",title:"Where it comes from · hyperopia",body:"Greek hyper=beyond + ops=eye + -ia=condition"},"wd-hypothesis":{src:"concept:34:words:8:def",route:"#/word/hypothesis",cta:"Open the word card",title:"hypothesis",roman:"h-ay-p-AH-th-uh-s-uh-s",body:"a proposition set forth to explain some occurrence",clip:1},"wx-hypothesis":{src:"concept:34:words:8:ex",route:"#/word/hypothesis",cta:"Open the word card",title:"In a sentence · hypothesis",body:"a scientific hypothesis that survives experimental testing becomes a scientific theory",clip:1},"wh-hypothesis":{src:"concept:34:words:8:hook",route:"#/word/hypothesis",cta:"Open the word card",title:"Remember it · hypothesis",body:"A hypoTHESIS is a THESIS placed UNDER scrutiny — it literally contains the word THESIS inside it."},"wo-hypothesis":{src:"lore:hypothesis:0",route:"#/word/hypothesis",cta:"Open the word card",title:"Where it comes from · hypothesis",body:"Greek hypo = under + thesis = placing, proposition"},"wd-hypocrisy":{src:"concept:34:words:9:def",route:"#/word/hypocrisy",cta:"Open the word card",title:"hypocrisy",roman:"h-ih-p-AH-k-r-uh-s-ee",body:"pretending to something that one doesn't believe",clip:1},"wx-hypocrisy":{src:"concept:34:words:9:ex",route:"#/word/hypocrisy",cta:"Open the word card",title:"In a sentence · hypocrisy",body:"The politician's hypocrisy was exposed when reporters discovered he had broken the very law he championed.",clip:1},"wh-hypocrisy":{src:"concept:34:words:9:hook",route:"#/word/hypocrisy",cta:"Open the word card",title:"Remember it · hypocrisy",body:"HYPOcrites CRISP-ly say one thing and do another — spell the CRISIS of fakery: h-y-p-o-c-r-i-s-y."},"wo-hypocrisy":{src:"lore:hypocrisy:0",route:"#/word/hypocrisy",cta:"Open the word card",title:"Where it comes from · hypocrisy",body:"Greek hypokrīsis = acting on stage, pretense"},"wd-hypochondria":{src:"concept:34:words:10:def",route:"#/word/hypochondria",cta:"Open the word card",title:"hypochondria",roman:"heye-puh-KAH-ndree-uh",body:"chronic and abnormal anxiety about imaginary symptoms and ailments",clip:1},"wx-hypochondria":{src:"concept:34:words:10:ex",route:"#/word/hypochondria",cta:"Open the word card",title:"In a sentence · hypochondria",body:"Whenever Marcus read about a new disease online, his hypochondria convinced him he had every symptom listed on the page.",clip:1},"wh-hypochondria":{src:"concept:34:words:10:hook",route:"#/word/hypochondria",cta:"Open the word card",title:"Remember it · hypochondria",body:"HYPO-CHONDRIA: always worried about what's UNDER your CHEST"},"wo-hypochondria":{src:"lore:hypochondria:0",route:"#/word/hypochondria",cta:"Open the word card",title:"Where it comes from · hypochondria",body:"Greek hypo = under + khondros = cartilage (of the breastbone)"},"wd-hypocaust":{src:"concept:34:words:11:def",route:"#/word/hypocaust",cta:"Open the word card",title:"hypocaust",roman:"HY-poh-kawst",body:"a central heating system of an ancient Roman building consisting of an underground furnace and a series of tile flues for distribution of the heat.",clip:1},"wx-hypocaust":{src:"concept:34:words:11:ex",route:"#/word/hypocaust",cta:"Open the word card",title:"In a sentence · hypocaust",body:"The Roman bathhouse was kept warm by a hypocaust, which circulated hot air beneath the tiled floors.",clip:1},"wh-hypocaust":{src:"concept:34:words:11:hook",route:"#/word/hypocaust",cta:"Open the word card",title:"Remember it · hypocaust",body:"A HYPOcaust burns HYPO (under) the floor — the Romans CAUSed heat below their feet."},"wo-hypocaust":{src:"lore:hypocaust:0",route:"#/word/hypocaust",cta:"Open the word card",title:"Where it comes from · hypocaust",body:"Greek hypo = under + kaustos = burned"},"wd-hypertension":{src:"concept:34:words:12:def",route:"#/word/hypertension",cta:"Open the word card",title:"hypertension",roman:"heye-per-TEH-nshuhn",body:"a common disorder in which blood pressure remains abnormally high (a reading of 140/90 mm Hg or greater)",clip:1},"wx-hypertension":{src:"concept:34:words:12:ex",route:"#/word/hypertension",cta:"Open the word card",title:"In a sentence · hypertension",body:"The doctor advised the patient to reduce salt intake and exercise regularly to manage his hypertension.",clip:1},"wh-hypertension":{src:"concept:34:words:12:hook",route:"#/word/hypertension",cta:"Open the word card",title:"Remember it · hypertension",body:"HyperTENSION is spelled with -SION not -TION — the TENSION is already in the word, don't change it."},"wo-hypertension":{src:"lore:hypertension:0",route:"#/word/hypertension",cta:"Open the word card",title:"Where it comes from · hypertension",body:"Greek hyper=over + Latin tensio=stretching/tension"},"wd-hypotension":{src:"concept:34:words:13:def",route:"#/word/hypotension",cta:"Open the word card",title:"hypotension",roman:"heye-poh-TEH-nshuhn",body:"abnormally low blood pressure",clip:1},"wx-hypotension":{src:"concept:34:words:13:ex",route:"#/word/hypotension",cta:"Open the word card",title:"In a sentence · hypotension",body:"After standing up too quickly, Marcus experienced a brief spell of hypotension that made the room spin.",clip:1},"wh-hypotension":{src:"concept:34:words:13:hook",route:"#/word/hypotension",cta:"Open the word card",title:"Remember it · hypotension",body:"HypoTENSION is LOW blood TENSION (pressure) — hypo pulls the number DOWN, hyper pushes it UP."},"wo-hypotension":{src:"lore:hypotension:0",route:"#/word/hypotension",cta:"Open the word card",title:"Where it comes from · hypotension",body:"Greek hypo = under + Latin tensio = stretching, pressure"},"wd-hypoglycemia":{src:"concept:34:words:15:def",route:"#/word/hypoglycemia",cta:"Open the word card",title:"hypoglycemia",roman:"heye-poh-gleye-SEE-mee-uh",body:"abnormally low blood sugar usually resulting from excessive insulin or a poor diet",clip:1},"wx-hypoglycemia":{src:"concept:34:words:15:ex",route:"#/word/hypoglycemia",cta:"Open the word card",title:"In a sentence · hypoglycemia",body:"The athlete felt dizzy and shaky during practice, and her doctor later diagnosed her with hypoglycemia.",clip:1},"wh-hypoglycemia":{src:"concept:34:words:15:hook",route:"#/word/hypoglycemia",cta:"Open the word card",title:"Remember it · hypoglycemia",body:"HypoGLYCEMIA: GLYCE sounds like GLYCERIN (sweet) — too LITTLE sugar in the blood, so you feel icky: -emia at the end."},"wo-hypoglycemia":{src:"lore:hypoglycemia:0",route:"#/word/hypoglycemia",cta:"Open the word card",title:"Where it comes from · hypoglycemia",body:"Greek hypo = under + glykys = sweet + haima = blood"},"li-u46":{src:"concept:35:concept",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega-",body:'Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary. Learning them unlocks everything from microscope to megalomania.'},"lc-u46-0":{src:"concept:35:cards:0",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega- · auto- = Self",body:"Automaton (auto- + matos = acting) = acts by itself. Autophagy (auto- + phagein = eat) = a cell digests itself. Autodidact (auto- + didaskein = teach) = self-taught person. Autocracy (auto- + kratos = rule) = rule by one person alone. Autonomy (auto- + nomos = law) = self-governance."},"lc-u46-1":{src:"concept:35:cards:1",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega- · tele- = Far",body:"Telepathy (tele- + pathos) = feeling from far away. Teleology (tele- + logos) = study of purposes/ends. Telekinesis (tele- + kinesis = movement) = moving things from a distance. Telegraph = write from far. Telescope = see far. Telemetry = measure from far (used in spacecraft)."},"lc-u46-2":{src:"concept:35:cards:2",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega- · micro- vs macro-",body:"Microcosm (mikros = small + kosmos) = small world. Macrocosm = the large or entire world. Microscope = looks at tiny things. Macroscopic = visible to the naked eye. Microphone = makes small voices large. Macroeconomics = large-scale economics. Small vs large — one prefix difference."},"lc-u46-3":{src:"concept:35:cards:3",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega- · mega- = Very Large",body:"Megalomania (mega- + mania) = delusions of great power. Megalopolis (mega- + polis = city) = a vast metropolitan area. Megalith (mega- + lithos = stone) = a very large stone (like Stonehenge). Megahertz = one million cycles per second. mega- became a general intensifier in everyday language."},"lc-u46-4":{src:"concept:35:cards:4",route:"#/stop/u46",cta:"Open this stop",title:"auto- / tele- / micro- / macro- / mega- · Spelling Traps",body:"Automaton = A-U-T-O-M-A-T-O-N (singular); Greek plural = automata. Telepathy ends in -thy not -tee. Megalomaniac = M-E-G-A-L-O-M-A-N-I-A-C. Autodidact = A-U-T-O-D-I-D-A-C-T. Each is built precisely from Greek parts — if you know the roots, you can spell the word."},"uq-u46-0":{src:"unit:u46:qs:0",route:"#/stop/u46",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “auto- / tele- / micro- / macro- / mega-”?",opts:['Five Greek prefixes of size and distance — from "self" to "far," from "tiny" to "enormous." These appear in science, technology, and everyday vocabulary.','The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of."],after:"From “auto- / tele- / micro- / macro- / mega-”."}},"uq-u46-3":{src:"unit:u46:qs:3",route:"#/stop/u46",cta:"Open this stop",title:"Whose hook?",play:{q:"“An ▁▁▁ is ONE robot acting on its own — singular, one T, ends in -on.” — which word is this hook about?",opts:["automaton","autophagy","autodidact","autocracy"],after:"From “auto- / tele- / micro- / macro- / mega-”."}},"wd-automaton":{src:"concept:35:words:0:def",route:"#/word/automaton",cta:"Open the word card",title:"automaton",roman:"aw-t-AH-m-uh-t-ah-n",body:"another word for a robot",clip:1},"wx-automaton":{src:"concept:35:words:0:ex",route:"#/word/automaton",cta:"Open the word card",title:"In a sentence · automaton",body:"only an automaton wouldn't have noticed",clip:1},"wh-automaton":{src:"concept:35:words:0:hook",route:"#/word/automaton",cta:"Open the word card",title:"Remember it · automaton",body:"An autoMATon is ONE robot acting on its own — singular, one T, ends in -on."},"wo-automaton":{src:"lore:automaton:0",route:"#/word/automaton",cta:"Open the word card",title:"Where it comes from · automaton",body:"Greek automatos = acting of itself"},"wd-autophagy":{src:"concept:35:words:1:def",route:"#/word/autophagy",cta:"Open the word card",title:"autophagy",roman:"aw-TOF-uh-jee",body:"The biological process by which a cell breaks down and recycles its own damaged or unnecessary components.",clip:1},"wx-autophagy":{src:"concept:35:words:1:ex",route:"#/word/autophagy",cta:"Open the word card",title:"In a sentence · autophagy",body:"Scientists discovered that autophagy helps cells survive periods of starvation by digesting their own proteins for energy.",clip:1},"wh-autophagy":{src:"concept:35:words:1:hook",route:"#/word/autophagy",cta:"Open the word card",title:"Remember it · autophagy",body:"AUTO (self) + PHAGY (eating) — the cell eats itself"},"wo-autophagy":{src:"lore:autophagy:0",route:"#/word/autophagy",cta:"Open the word card",title:"Where it comes from · autophagy",body:"Greek autos = self + phagein = to eat"},"wd-autodidact":{src:"concept:35:words:2:def",route:"#/word/autodidact",cta:"Open the word card",title:"autodidact",roman:"aw-toh-DY-dakt",body:"a person who has taught himself",clip:1},"wx-autodidact":{src:"concept:35:words:2:ex",route:"#/word/autodidact",cta:"Open the word card",title:"In a sentence · autodidact",body:"The famous inventor was a proud autodidact who had never attended college yet revolutionized electrical engineering.",clip:1},"wh-autodidact":{src:"concept:35:words:2:hook",route:"#/word/autodidact",cta:"Open the word card",title:"Remember it · autodidact",body:"AUTO (self) + DIDACT (teach) = self-taught person."},"wo-autodidact":{src:"lore:autodidact:0",route:"#/word/autodidact",cta:"Open the word card",title:"Where it comes from · autodidact",body:"Greek autos = self + didaskein = to teach"},"wd-autocracy":{src:"concept:35:words:3:def",route:"#/word/autocracy",cta:"Open the word card",title:"autocracy",roman:"aw-TAH-kruh-see",body:"a political system governed by a single individual",clip:1},"wx-autocracy":{src:"concept:35:words:3:ex",route:"#/word/autocracy",cta:"Open the word card",title:"In a sentence · autocracy",body:"The citizens grew frustrated living under an autocracy where a single ruler made every decision without question.",clip:1},"wh-autocracy":{src:"concept:35:words:3:hook",route:"#/word/autocracy",cta:"Open the word card",title:"Remember it · autocracy",body:"AUTO-CRACY: one ruler rules by themselves — C-R-A-C-Y, like democracy but with AUTO in front."},"wo-autocracy":{src:"lore:autocracy:0",route:"#/word/autocracy",cta:"Open the word card",title:"Where it comes from · autocracy",body:"Greek autos = self + kratos = power, rule"},"wd-autonomy":{src:"concept:35:words:4:def",route:"#/word/autonomy",cta:"Open the word card",title:"autonomy",roman:"aw-TAH-nuh-mee",body:"immunity from arbitrary exercise of authority: political independence",clip:1},"wx-autonomy":{src:"concept:35:words:4:ex",route:"#/word/autonomy",cta:"Open the word card",title:"In a sentence · autonomy",body:"The teenagers appreciated the autonomy their teacher gave them to choose their own research topics.",clip:1},"wh-autonomy":{src:"concept:35:words:4:hook",route:"#/word/autonomy",cta:"Open the word card",title:"Remember it · autonomy",body:"AutoNOMy = self-law — NOM not NAM, think of NORMS you set for yourself."},"wo-autonomy":{src:"lore:autonomy:0",route:"#/word/autonomy",cta:"Open the word card",title:"Where it comes from · autonomy",body:"Greek autos = self + nomos = law"},"wd-telepathy":{src:"concept:35:words:5:def",route:"#/word/telepathy",cta:"Open the word card",title:"telepathy",roman:"t-uh-l-EH-p-uh-th-ee",body:"communication between minds",clip:1},"wx-telepathy":{src:"concept:35:words:5:ex",route:"#/word/telepathy",cta:"Open the word card",title:"In a sentence · telepathy",body:"The twins seemed to communicate by telepathy, finishing each other's sentences without hesitation.",clip:1},"wh-telepathy":{src:"concept:35:words:5:hook",route:"#/word/telepathy",cta:"Open the word card",title:"Remember it · telepathy",body:"TELEPATHY: feelings travel a long TELE-PATH-Y — the PATH is right there in the middle of the word!"},"wo-telepathy":{src:"lore:telepathy:0",route:"#/word/telepathy",cta:"Open the word card",title:"Where it comes from · telepathy",body:"Greek tele = far + pathos = feeling"},"wd-teleology":{src:"concept:35:words:6:def",route:"#/word/teleology",cta:"Open the word card",title:"teleology",roman:"TEE-lee-aw-luh-jee",body:"a philosophical doctrine that explains phenomena by the purposes or goals they serve rather than by prior causes",clip:1},"wx-teleology":{src:"concept:35:words:6:ex",route:"#/word/teleology",cta:"Open the word card",title:"In a sentence · teleology",body:"In philosophy class, we debated teleology — whether nature has built-in purposes, like how eyes seem perfectly designed for seeing.",clip:1},"wh-teleology":{src:"concept:35:words:6:hook",route:"#/word/teleology",cta:"Open the word card",title:"Remember it · teleology",body:"TELE-OLOGY — studying the TELOS (end goal) of everything"},"wo-teleology":{src:"lore:teleology:0",route:"#/word/teleology",cta:"Open the word card",title:"Where it comes from · teleology",body:"Greek telos = end, purpose + logos = study"},"wd-telekinesis":{src:"concept:35:words:7:def",route:"#/word/telekinesis",cta:"Open the word card",title:"telekinesis",roman:"teh-leh-kih-NEE-sis",body:"the power to move something by thinking about it without the application of physical force",clip:1},"wx-telekinesis":{src:"concept:35:words:7:ex",route:"#/word/telekinesis",cta:"Open the word card",title:"In a sentence · telekinesis",body:"In the movie, the girl used telekinesis to slam the door without ever touching it.",clip:1},"wh-telekinesis":{src:"concept:35:words:7:hook",route:"#/word/telekinesis",cta:"Open the word card",title:"Remember it · telekinesis",body:"TELE (far) + KINESIS (movement) — moving things from far away; remember 'kinetic energy' for the 'kinesis' part."},"wo-telekinesis":{src:"lore:telekinesis:0",route:"#/word/telekinesis",cta:"Open the word card",title:"Where it comes from · telekinesis",body:"Ancient Greek (to 1453): κινέω (Ancient Greek (to 1453))"},"wd-telegraph":{src:"concept:35:words:8:def",route:"#/word/telegraph",cta:"Open the word card",title:"telegraph",roman:"TEH-luh-graf",body:"apparatus used to communicate at a distance over a wire (usually in Morse code)",clip:1},"wx-telegraph":{src:"concept:35:words:8:ex",route:"#/word/telegraph",cta:"Open the word card",title:"In a sentence · telegraph",body:"The telegraph revolutionized long-distance communication in the nineteenth century, allowing news to travel in minutes rather than days.",clip:1},"wh-telegraph":{src:"concept:35:words:8:hook",route:"#/word/telegraph",cta:"Open the word card",title:"Remember it · telegraph",body:"A TELEGRAPH GRAPHS writing from FAR away — ends in -GRAPH like photograph and autograph!"},"wo-telegraph":{src:"lore:telegraph:0",route:"#/word/telegraph",cta:"Open the word card",title:"Where it comes from · telegraph",body:"Greek tele = far + graphein = to write"},"wd-telescope":{src:"concept:35:words:9:def",route:"#/word/telescope",cta:"Open the word card",title:"telescope",roman:"TEH-luh-skohp",body:"a magnifier of images of distant objects",clip:1},"wx-telescope":{src:"concept:35:words:9:ex",route:"#/word/telescope",cta:"Open the word card",title:"In a sentence · telescope",body:"In the accident, the cars telescoped",clip:1},"wh-telescope":{src:"concept:35:words:9:hook",route:"#/word/telescope",cta:"Open the word card",title:"Remember it · telescope",body:"A TELESCOPE lets you SCOPE (look) from TELE (far) — scope out distant stars!"},"wo-telescope":{src:"lore:telescope:0",route:"#/word/telescope",cta:"Open the word card",title:"Where it comes from · telescope",body:"Greek tele = far + skopein = to look/observe"},"wd-microcosm":{src:"concept:35:words:10:def",route:"#/word/microcosm",cta:"Open the word card",title:"microcosm",roman:"m-AY-k-r-uh-k-ah-z-uh-m",body:"a world in miniature",clip:1},"wx-microcosm":{src:"concept:35:words:10:ex",route:"#/word/microcosm",cta:"Open the word card",title:"In a sentence · microcosm",body:"The tiny tide pool was a microcosm of the ocean, filled with crabs, snails, and darting fish.",clip:1},"wh-microcosm":{src:"concept:35:words:10:hook",route:"#/word/microcosm",cta:"Open the word card",title:"Remember it · microcosm",body:"A microCOSM is a small COSMos — spot COSM inside, like cosmonaut, and you'll never misspell it."},"wo-microcosm":{src:"lore:microcosm:0",route:"#/word/microcosm",cta:"Open the word card",title:"Where it comes from · microcosm",body:"Greek mikros = small + Greek kosmos = world/order"},"wd-macrocosm":{src:"concept:35:words:11:def",route:"#/word/macrocosm",cta:"Open the word card",title:"macrocosm",roman:"MAK-roh-koz-um",body:"everything that exists anywhere; the whole universe",clip:1},"wx-macrocosm":{src:"concept:35:words:11:ex",route:"#/word/macrocosm",cta:"Open the word card",title:"In a sentence · macrocosm",body:"The philosopher argued that every human life is a microcosm that reflects the patterns of the larger macrocosm.",clip:1},"wh-macrocosm":{src:"concept:35:words:11:hook",route:"#/word/macrocosm",cta:"Open the word card",title:"Remember it · macrocosm",body:"MACROcosm = MACRO (big) + COSM (cosmos/universe)"},"wo-macrocosm":{src:"lore:macrocosm:0",route:"#/word/macrocosm",cta:"Open the word card",title:"Where it comes from · macrocosm",body:"Greek makros = large + kosmos = world/order"},"wd-microscope":{src:"concept:35:words:12:def",route:"#/word/microscope",cta:"Open the word card",title:"microscope",roman:"MEYE-kruh-skohp",body:"magnifier of the image of small objects",clip:1},"wx-microscope":{src:"concept:35:words:12:ex",route:"#/word/microscope",cta:"Open the word card",title:"In a sentence · microscope",body:"the invention of the microscope led to the discovery of the cell",clip:1},"wh-microscope":{src:"concept:35:words:12:hook",route:"#/word/microscope",cta:"Open the word card",title:"Remember it · microscope",body:"A MICROSCOPE lets you SCOPE out (look at) MICRO (tiny) things—micro+scope."},"wo-microscope":{src:"lore:microscope:0",route:"#/word/microscope",cta:"Open the word card",title:"Where it comes from · microscope",body:"Greek mikros=small + skopein=to look at"},"wd-megalomania":{src:"concept:35:words:14:def",route:"#/word/megalomania",cta:"Open the word card",title:"megalomania",roman:"meh-guh-loh-MAY-nee-uh",body:"a psychological state characterized by delusions of grandeur",clip:1},"wx-megalomania":{src:"concept:35:words:14:ex",route:"#/word/megalomania",cta:"Open the word card",title:"In a sentence · megalomania",body:"The dictator's megalomania was evident when he ordered statues of himself placed in every public square in the country.",clip:1},"wh-megalomania":{src:"concept:35:words:14:hook",route:"#/word/megalomania",cta:"Open the word card",title:"Remember it · megalomania",body:"A megalomaniac thinks they're MEGA great to the point of MANIA — one L in megalo, double the delusion."},"wo-megalomania":{src:"lore:megalomania:0",route:"#/word/megalomania",cta:"Open the word card",title:"Where it comes from · megalomania",body:"Greek megas/megalo = great + mania = madness"},"wd-megalopolis":{src:"concept:35:words:15:def",route:"#/word/megalopolis",cta:"Open the word card",title:"megalopolis",roman:"meh-guh-LAH-puh-luhs",body:"a very large urban complex (usually involving several cities and towns)",clip:1},"wx-megalopolis":{src:"concept:35:words:15:ex",route:"#/word/megalopolis",cta:"Open the word card",title:"In a sentence · megalopolis",body:"The northeastern coast of the United States forms a megalopolis stretching from Boston all the way down to Washington, D.C.",clip:1},"wh-megalopolis":{src:"concept:35:words:15:hook",route:"#/word/megalopolis",cta:"Open the word card",title:"Remember it · megalopolis",body:"A MEGALOPOLIS is a MEGA POLIS — a super-city; 'polis' means city in Greek, just like metropolis."},"wo-megalopolis":{src:"lore:megalopolis:0",route:"#/word/megalopolis",cta:"Open the word card",title:"Where it comes from · megalopolis",body:"Greek megas = great + polis = city"},"wd-megalith":{src:"concept:35:words:16:def",route:"#/word/megalith",cta:"Open the word card",title:"megalith",roman:"MEG-uh-lith",body:"memorial consisting of a very large stone forming part of a prehistoric structure (especially in western Europe)",clip:1},"wx-megalith":{src:"concept:35:words:16:ex",route:"#/word/megalith",cta:"Open the word card",title:"In a sentence · megalith",body:"Each massive megalith at the ancient site weighed several tons and had been dragged miles across the plain.",clip:1},"wh-megalith":{src:"concept:35:words:16:hook",route:"#/word/megalith",cta:"Open the word card",title:"Remember it · megalith",body:"A MEGA LITH is a MEGA stone — think of Stonehenge; 'lith' always means stone, spelled L-I-T-H."},"wd-telemetry":{src:"concept:35:words:17:def",route:"#/word/telemetry",cta:"Open the word card",title:"telemetry",roman:"tuh-LEH-muh-tree",body:"automatic transmission and measurement of data from remote sources by wire or radio or other means",clip:1},"wx-telemetry":{src:"concept:35:words:17:ex",route:"#/word/telemetry",cta:"Open the word card",title:"In a sentence · telemetry",body:"Mission controllers monitored the astronaut's heart rate through telemetry sent directly from sensors aboard the spacecraft.",clip:1},"wh-telemetry":{src:"concept:35:words:17:hook",route:"#/word/telemetry",cta:"Open the word card",title:"Remember it · telemetry",body:"TELEMETRY MEASURES from afar — TELE+METRY, and METER is hiding right in the middle!"},"wo-telemetry":{src:"lore:telemetry:0",route:"#/word/telemetry",cta:"Open the word card",title:"Where it comes from · telemetry",body:"Greek tele = far + metron = measure"},"li-u47":{src:"concept:36:concept",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo-",body:"Five Greek scientific prefixes — life, earth, light, water, heat — forming the backbone of natural science vocabulary. Every science class uses them; every spelling bee tests them. All require ph not f."},"lc-u47-0":{src:"concept:36:cards:0",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo- · bio- = Life",body:"Biology = study of life. Biome = a life community. Biopsy (bio- + opsis = seeing) = visual examination of living tissue. Symbiosis (sym- + bio-) = living together mutually. Antibiotic (anti- + bio-) = substance that kills living organisms (bacteria). All life is bio-."},"lc-u47-1":{src:"concept:36:cards:1",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo- · geo- = Earth",body:"Geography = writing about the earth. Geology = study of earth. Geothermal = earth-heat. Geodesic (geo- + daiein = divide) = shortest path on a sphere. Geocentric = earth-centered view. Apogee (apo- + geo-) = point in orbit farthest from earth."},"lc-u47-2":{src:"concept:36:cards:2",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo- · photo- = Light",body:"Photosynthesis = plants make food from light. Photogenic = looks good in light. Photon = a particle of light. Photograph = written by light. Photophobia = sensitivity to light. ⚠️ All photo- words use ph — never f — because this is Greek."},"lc-u47-3":{src:"concept:36:cards:3",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo- · hydro- = Water",body:"Hydrolysis (hydro- + lysis = breaking) = breaking by water. Hydroponics = growing in water. Hydraulic (hydro- + aulos = pipe) = water through pipes. Hydrophobia = fear of water. Dehydrate = de- + hydro- = remove water from."},"lc-u47-4":{src:"concept:36:cards:4",route:"#/stop/u47",cta:"Open this stop",title:"bio- / geo- / photo- / hydro- / thermo- · thermo- = Heat",body:"Thermometer = measures heat. Thermostat (thermo- + statos = standing) = keeps heat steady. Thermodynamics = study of heat and energy. Endothermic (endo- = within) = absorbs heat. Exothermic (exo- = out) = releases heat. Note: geothermal combines both geo- and thermo- in one word."},"uq-u47-0":{src:"unit:u47:qs:0",route:"#/stop/u47",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “bio- / geo- / photo- / hydro- / thermo-”?",opts:["Five Greek scientific prefixes — life, earth, light, water, heat — forming the backbone of natural science vocabulary.",'The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of."],after:"From “bio- / geo- / photo- / hydro- / thermo-”."}},"uq-u47-3":{src:"unit:u47:qs:3",route:"#/stop/u47",cta:"Open this stop",title:"Whose hook?",play:{q:"“BIO + LOGY — every -logy word studies something; this one studies life (bio). Don't skip the 'o' in logy.” — which word is this hook about?",opts:["biology","biome","biopsy","symbiosis"],after:"From “bio- / geo- / photo- / hydro- / thermo-”."}},"wd-biology":{src:"concept:36:words:0:def",route:"#/word/biology",cta:"Open the word card",title:"biology",roman:"beye-AH-luh-jee",body:"the science that studies living organisms",clip:1},"wx-biology":{src:"concept:36:words:0:ex",route:"#/word/biology",cta:"Open the word card",title:"In a sentence · biology",body:"the biology of viruses",clip:1},"wh-biology":{src:"concept:36:words:0:hook",route:"#/word/biology",cta:"Open the word card",title:"Remember it · biology",body:"BIO + LOGY — every -logy word studies something; this one studies life (bio). Don't skip the 'o' in logy."},"wo-biology":{src:"lore:biology:0",route:"#/word/biology",cta:"Open the word card",title:"Where it comes from · biology",body:"Greek bios = life + logos = study"},"wd-biome":{src:"concept:36:words:1:def",route:"#/word/biome",cta:"Open the word card",title:"biome",roman:"BEYE-ohm",body:"a major biotic community characterized by the dominant forms of plant life and the prevailing climate",clip:1},"wx-biome":{src:"concept:36:words:1:ex",route:"#/word/biome",cta:"Open the word card",title:"In a sentence · biome",body:"The rainforest biome supports more species of plants and animals than any other on Earth.",clip:1},"wh-biome":{src:"concept:36:words:1:hook",route:"#/word/biome",cta:"Open the word card",title:"Remember it · biome",body:"A BIOMEis a living HOME — HOME and BIOME both end in '-ome,' and every biome is a home for life."},"wd-biopsy":{src:"concept:36:words:2:def",route:"#/word/biopsy",cta:"Open the word card",title:"biopsy",roman:"BEYE-ah-psee",body:"examination of tissues or liquids from the living body to determine the existence or cause of a disease",clip:1},"wx-biopsy":{src:"concept:36:words:2:ex",route:"#/word/biopsy",cta:"Open the word card",title:"In a sentence · biopsy",body:"The doctor ordered a biopsy of the unusual tissue to determine whether it was cancerous.",clip:1},"wh-biopsy":{src:"concept:36:words:2:hook",route:"#/word/biopsy",cta:"Open the word card",title:"Remember it · biopsy",body:"A bioPS-Y is a doctor's way of taking a SPY look at living tissue — bioPSY ends in -PSY like autoPSY."},"wd-symbiosis":{src:"concept:36:words:3:def",route:"#/word/symbiosis",cta:"Open the word card",title:"symbiosis",roman:"sih-mbeye-OH-suhs",body:"the relation between two different species of organisms that are interdependent; each gains benefits from the other",clip:1},"wx-symbiosis":{src:"concept:36:words:3:ex",route:"#/word/symbiosis",cta:"Open the word card",title:"In a sentence · symbiosis",body:"The clownfish and the sea anemone demonstrate a classic example of symbiosis, each protecting and benefiting the other in the ocean.",clip:1},"wh-symbiosis":{src:"concept:36:words:3:hook",route:"#/word/symbiosis",cta:"Open the word card",title:"Remember it · symbiosis",body:"SYMBIOsis — SYM + BIO: two species sharing one BIO(logy) class together, the perfect partnership."},"wo-symbiosis":{src:"lore:symbiosis:0",route:"#/word/symbiosis",cta:"Open the word card",title:"Where it comes from · symbiosis",body:"Greek symbiosis = living together (syn=together + bios=life)"},"wd-antibiotic":{src:"concept:36:words:4:def",route:"#/word/antibiotic",cta:"Open the word card",title:"antibiotic",roman:"a-ntee-beye-AH-tihk",body:"a chemical substance derivable from a mold or bacterium that can kill microorganisms and cure bacterial infections",clip:1},"wx-antibiotic":{src:"concept:36:words:4:ex",route:"#/word/antibiotic",cta:"Open the word card",title:"In a sentence · antibiotic",body:"when antibiotics were first discovered they were called wonder drugs",clip:1},"wh-antibiotic":{src:"concept:36:words:4:hook",route:"#/word/antibiotic",cta:"Open the word card",title:"Remember it · antibiotic",body:"ANTI-BIO-TIC: BIO means life — an antibiotic is AGAINST the life of bacteria; think of a BIOlogist's worst enemy ending in -TIC."},"wo-antibiotic":{src:"lore:antibiotic:0",route:"#/word/antibiotic",cta:"Open the word card",title:"Where it comes from · antibiotic",body:"Greek anti = against + bios = life"},"wd-geography":{src:"concept:36:words:5:def",route:"#/word/geography",cta:"Open the word card",title:"geography",roman:"jee-AH-gruh-fee",body:"study of the earth's surface; includes people's responses to topography and climate and soil and vegetation",clip:1},"wx-geography":{src:"concept:36:words:5:ex",route:"#/word/geography",cta:"Open the word card",title:"In a sentence · geography",body:"In geography class, students traced the path of the Amazon River across a giant wall map.",clip:1},"wh-geography":{src:"concept:36:words:5:hook",route:"#/word/geography",cta:"Open the word card",title:"Remember it · geography",body:"GEOGRAPHY = GEO+GRAPHY — writing (GRAPHY) about the earth (GEO); keep the PH, it's a GRAPH of the globe."},"wo-geography":{src:"lore:geography:0",route:"#/word/geography",cta:"Open the word card",title:"Where it comes from · geography",body:"Greek ge = earth + graphein = to write"},"wd-geology":{src:"concept:36:words:6:def",route:"#/word/geology",cta:"Open the word card",title:"geology",roman:"jee-AH-luh-jee",body:"a science that deals with the history of the earth as recorded in rocks",clip:1},"wx-geology":{src:"concept:36:words:6:ex",route:"#/word/geology",cta:"Open the word card",title:"In a sentence · geology",body:"Her geology class took a field trip to study the layers of rock exposed along the canyon wall.",clip:1},"wh-geology":{src:"concept:36:words:6:hook",route:"#/word/geology",cta:"Open the word card",title:"Remember it · geology",body:"GEO-logy: the earth (GEO) keeps a LOG of its own history in rocks."},"wo-geology":{src:"lore:geology:0",route:"#/word/geology",cta:"Open the word card",title:"Where it comes from · geology",body:"Greek ge = earth + logos = study"},"wd-geothermal":{src:"concept:36:words:7:def",route:"#/word/geothermal",cta:"Open the word card",title:"geothermal",roman:"jee-oh-THUR-muhl",body:"of or relating to the heat in the interior of the earth",clip:1},"wx-geothermal":{src:"concept:36:words:7:ex",route:"#/word/geothermal",cta:"Open the word card",title:"In a sentence · geothermal",body:"Iceland generates most of its electricity from geothermal energy by harnessing the intense heat produced by the volcanic activity beneath the island.",clip:1},"wh-geothermal":{src:"concept:36:words:7:hook",route:"#/word/geothermal",cta:"Open the word card",title:"Remember it · geothermal",body:"GEO-THERM-AL: the earth's THERMOSTAT turned way up — remember geo + therm + al."},"wo-geothermal":{src:"lore:geothermal:0",route:"#/word/geothermal",cta:"Open the word card",title:"Where it comes from · geothermal",body:"Greek geo = earth + therme = heat"},"wd-geodesic":{src:"concept:36:words:8:def",route:"#/word/geodesic",cta:"Open the word card",title:"geodesic",roman:"jee-uh-DEH-sihk",body:"in mathematics, the shortest line between two points on a mathematically defined surface (as a straight line on a plane or an arc of a great circle on a sphere)",clip:1},"wx-geodesic":{src:"concept:36:words:8:ex",route:"#/word/geodesic",cta:"Open the word card",title:"In a sentence · geodesic",body:"Buckminster Fuller's geodesic dome became an iconic architectural structure admired for its strength and efficiency.",clip:1},"wh-geodesic":{src:"concept:36:words:8:hook",route:"#/word/geodesic",cta:"Open the word card",title:"Remember it · geodesic",body:"GEODESIC ends in -SIC not -SICK — the shortest path on earth never gets sick, it stays trim."},"wo-geodesic":{src:"lore:geodesic:0",route:"#/word/geodesic",cta:"Open the word card",title:"Where it comes from · geodesic",body:"Greek ge = earth + daiesthai = to divide"},"wd-photosynthesis":{src:"concept:36:words:9:def",route:"#/word/photosynthesis",cta:"Open the word card",title:"photosynthesis",roman:"f-oh-t-oh-s-IH-n-th-uh-s-ih-s",body:"the formation of carbohydrates from carbon dioxide and a source of hydrogen in chlorophyll-containing cells",clip:1},"wx-photosynthesis":{src:"concept:36:words:9:ex",route:"#/word/photosynthesis",cta:"Open the word card",title:"In a sentence · photosynthesis",body:"During photosynthesis, the leaves of the sunflower convert sunlight into the energy it needs to grow.",clip:1},"wh-photosynthesis":{src:"concept:36:words:9:hook",route:"#/word/photosynthesis",cta:"Open the word card",title:"Remember it · photosynthesis",body:"PHOTO-SYN-THE-SIS: plants use PHOTO (light) to SYN-THE-SIZE food — end it with -SIS like 'crisis.'"},"wo-photosynthesis":{src:"lore:photosynthesis:0",route:"#/word/photosynthesis",cta:"Open the word card",title:"Where it comes from · photosynthesis",body:"Greek photos = light + synthesis = putting together"},"wd-photogenic":{src:"concept:36:words:10:def",route:"#/word/photogenic",cta:"Open the word card",title:"photogenic",roman:"foh-tuh-JEH-nihk",body:"looking attractive in photographs",clip:1},"wx-photogenic":{src:"concept:36:words:10:ex",route:"#/word/photogenic",cta:"Open the word card",title:"In a sentence · photogenic",body:"The golden retriever was so photogenic that every snapshot of him looked like a professional portrait.",clip:1},"wh-photogenic":{src:"concept:36:words:10:hook",route:"#/word/photogenic",cta:"Open the word card",title:"Remember it · photogenic",body:"PHOTOGENic people are born (GENerated) to look great in the light — no extra E."},"wo-photogenic":{src:"lore:photogenic:0",route:"#/word/photogenic",cta:"Open the word card",title:"Where it comes from · photogenic",body:"Greek phos = light + Greek genos = born/produced"},"wd-photon":{src:"concept:36:words:11:def",route:"#/word/photon",cta:"Open the word card",title:"photon",roman:"FOH-tahn",body:"a quantum of electromagnetic radiation; an elementary particle that is its own antiparticle",clip:1},"wx-photon":{src:"concept:36:words:11:ex",route:"#/word/photon",cta:"Open the word card",title:"In a sentence · photon",body:"A single photon of light struck the sensor and triggered the alarm system.",clip:1},"wh-photon":{src:"concept:36:words:11:hook",route:"#/word/photon",cta:"Open the word card",title:"Remember it · photon",body:"A PHOTon is a particle of light — PH not F, just like PHOTO, its parent word."},"wd-hydrolysis":{src:"concept:36:words:12:def",route:"#/word/hydrolysis",cta:"Open the word card",title:"hydrolysis",roman:"h-ay-d-r-AH-l-uh-s-uh-s",body:"chemical decomposition by reacting with water",clip:1},"wx-hydrolysis":{src:"concept:36:words:12:ex",route:"#/word/hydrolysis",cta:"Open the word card",title:"In a sentence · hydrolysis",body:"During hydrolysis, the complex starch molecule breaks apart when it reacts with water.",clip:1},"wh-hydrolysis":{src:"concept:36:words:12:hook",route:"#/word/hydrolysis",cta:"Open the word card",title:"Remember it · hydrolysis",body:"HY-DROL-Y-SIS: water (hydro) causes a loosening (lysis) — remember SIS at the end like 'analysis.'"},"wo-hydrolysis":{src:"lore:hydrolysis:0",route:"#/word/hydrolysis",cta:"Open the word card",title:"Where it comes from · hydrolysis",body:"Greek hydro = water + lysis = loosening"},"wd-hydraulic":{src:"concept:36:words:14:def",route:"#/word/hydraulic",cta:"Open the word card",title:"hydraulic",roman:"h-ay-d-r-AW-l-ih-k",body:"employing water or other liquids in motion",clip:1},"wx-hydraulic":{src:"concept:36:words:14:ex",route:"#/word/hydraulic",cta:"Open the word card",title:"In a sentence · hydraulic",body:"The engineering students marveled at how the hydraulic lift at the auto shop could raise an entire vehicle effortlessly using only the power of pressurized fluid flowing through a compact network of metal tubes.",clip:1},"wh-hydraulic":{src:"concept:36:words:14:hook",route:"#/word/hydraulic",cta:"Open the word card",title:"Remember it · hydraulic",body:"HydrAULic pipes HAUL water with powerful force — remember the AU in HAUL."},"wo-hydraulic":{src:"lore:hydraulic:0",route:"#/word/hydraulic",cta:"Open the word card",title:"Where it comes from · hydraulic",body:"Greek hydor = water + aulos = pipe"},"wd-hydrophobia":{src:"concept:36:words:15:def",route:"#/word/hydrophobia",cta:"Open the word card",title:"hydrophobia",roman:"heye-druh-FOH-bee-uh",body:"a symptom of rabies in humans consisting of an aversion to swallowing liquids",clip:1},"wx-hydrophobia":{src:"concept:36:words:15:ex",route:"#/word/hydrophobia",cta:"Open the word card",title:"In a sentence · hydrophobia",body:"The doctor explained that hydrophobia in the patient was an alarming sign that the rabies infection had progressed severely.",clip:1},"wh-hydrophobia":{src:"concept:36:words:15:hook",route:"#/word/hydrophobia",cta:"Open the word card",title:"Remember it · hydrophobia",body:"A HYDROphobic person FEARS water — hydro (water) + phobia (fear) — both Greek roots drip with meaning."},"wo-hydrophobia":{src:"lore:hydrophobia:0",route:"#/word/hydrophobia",cta:"Open the word card",title:"Where it comes from · hydrophobia",body:"Greek hydro = water + phobos = fear"},"wd-thermometer":{src:"concept:36:words:16:def",route:"#/word/thermometer",cta:"Open the word card",title:"thermometer",roman:"ther-MAH-muh-ter",body:"measuring instrument for measuring temperature",clip:1},"wx-thermometer":{src:"concept:36:words:16:ex",route:"#/word/thermometer",cta:"Open the word card",title:"In a sentence · thermometer",body:"The nurse placed a thermometer under the child's tongue to check whether his fever had gone down overnight.",clip:1},"wh-thermometer":{src:"concept:36:words:16:hook",route:"#/word/thermometer",cta:"Open the word card",title:"Remember it · thermometer",body:"THERMO-METER: a METER that measures THERMO (heat) — meter is always spelled M-E-T-E-R, never miter."},"wo-thermometer":{src:"lore:thermometer:0",route:"#/word/thermometer",cta:"Open the word card",title:"Where it comes from · thermometer",body:"Greek therme = heat + metron = measure"},"wd-thermostat":{src:"concept:36:words:17:def",route:"#/word/thermostat",cta:"Open the word card",title:"thermostat",roman:"THUR-muh-stat",body:"a regulator for automatically regulating temperature by starting or stopping the supply of heat",clip:1},"wx-thermostat":{src:"concept:36:words:17:ex",route:"#/word/thermostat",cta:"Open the word card",title:"In a sentence · thermostat",body:"She programmed the thermostat to lower the heat at night and warm the house again before her alarm went off each morning.",clip:1},"wh-thermostat":{src:"concept:36:words:17:hook",route:"#/word/thermostat",cta:"Open the word card",title:"Remember it · thermostat",body:"THERMO-STAT: it makes heat STAY STATIC — a thermoSTAT keeps temperature STATionary, spelled S-T-A-T."},"wo-thermostat":{src:"lore:thermostat:0",route:"#/word/thermostat",cta:"Open the word card",title:"Where it comes from · thermostat",body:"Greek therme = heat + statos = standing, stationary"},"li-u48":{src:"concept:37:concept",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem-",body:"Six Greek body-system prefixes that unlock all medical specialist names and condition vocabulary. Know these six and the science section of any spelling bee becomes a pattern-matching exercise."},"lc-u48-0":{src:"concept:37:cards:0",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem- · neuro- = Nerve",body:"Neurology = study of the nervous system. Neuropathy = nerve disease. Neuroticism = anxiety-prone personality trait. Neurosis = a mild mental disorder. Neurotransmitter = chemical messenger between nerve cells. The eu = /yoor/ pronunciation catches many spellers off guard."},"lc-u48-1":{src:"concept:37:cards:1",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem- · cardio- = Heart",body:"Cardiology = study of the heart. Cardiovascular = heart and blood vessels. Electrocardiogram = E-L-E-C-T-R-O-C-A-R-D-I-O-G-R-A-M = record of heart electricity (EKG). Myocardium (myo- = muscle) = the heart muscle. Pericardium (peri- = around) = membrane surrounding the heart."},"lc-u48-2":{src:"concept:37:cards:2",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem- · osteo- = Bone / psycho- = Mind",body:"Osteoporosis (osteo- + poros = passage + -osis) = bones becoming porous and fragile. Osteopathy = treating disease through bone/tissue manipulation. Psychology = study of the mind. Psychosis = a serious mental disorder. Psychosomatic (psycho- + soma = body) = mind-body interaction."},"lc-u48-3":{src:"concept:37:cards:3",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem- · derm- = Skin",body:"Dermatology = study of skin. Dermatitis = skin inflammation. Epidermis (epi- + derma) = outer skin layer. Hypodermic (hypo- + derm-) = under the skin = type of injection. Taxidermy (taxi- = arrange + derma) = arranging skin = mounting animals."},"lc-u48-4":{src:"concept:37:cards:4",route:"#/stop/u48",cta:"Open this stop",title:"neuro- / cardio- / osteo- / psycho- / derm- / hem- · hem- = Blood",body:"Hematology = study of blood. Hemoglobin = the oxygen-carrying protein in blood. Hemorrhage (hem- + rhegnynai = burst) = blood bursting out. ⚠️ British spelling: haemorrhage — both are correct. Hemophilia (hem- + philia = love) = condition where blood loves to flow (does not clot properly)."},"uq-u48-0":{src:"unit:u48:qs:0",route:"#/stop/u48",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “neuro- / cardio- / osteo- / psycho- / derm- / hem-”?",opts:["Six Greek body-system prefixes that unlock all medical specialist names and condition vocabulary.",'The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of."],after:"From “neuro- / cardio- / osteo- / psycho- / derm- / hem-”."}},"uq-u48-3":{src:"unit:u48:qs:3",route:"#/stop/u48",cta:"Open this stop",title:"Whose hook?",play:{q:"“NEURO-LOGY: nerves need LOGIC — study them with ▁▁▁.” — which word is this hook about?",opts:["neurology","neuropathy","neuroticism","cardiology"],after:"From “neuro- / cardio- / osteo- / psycho- / derm- / hem-”."}},"wd-neurology":{src:"concept:37:words:0:def",route:"#/word/neurology",cta:"Open the word card",title:"neurology",roman:"nuu-RAH-luh-jee",body:"the branch of medical science that deals with the nervous system",clip:1},"wx-neurology":{src:"concept:37:words:0:ex",route:"#/word/neurology",cta:"Open the word card",title:"In a sentence · neurology",body:"She decided to specialize in neurology after becoming fascinated by how the brain controls every movement we make.",clip:1},"wh-neurology":{src:"concept:37:words:0:hook",route:"#/word/neurology",cta:"Open the word card",title:"Remember it · neurology",body:"NEURO-LOGY: nerves need LOGIC — study them with NEUROLOgy."},"wo-neurology":{src:"lore:neurology:0",route:"#/word/neurology",cta:"Open the word card",title:"Where it comes from · neurology",body:"Greek neuron = nerve + logos = study"},"wd-neuropathy":{src:"concept:37:words:1:def",route:"#/word/neuropathy",cta:"Open the word card",title:"neuropathy",roman:"NUU-roh-pa-thee",body:"any pathology of the peripheral nerves",clip:1},"wx-neuropathy":{src:"concept:37:words:1:ex",route:"#/word/neuropathy",cta:"Open the word card",title:"In a sentence · neuropathy",body:"The diabetic patient developed neuropathy in her feet, causing a constant tingling and numbness.",clip:1},"wh-neuropathy":{src:"concept:37:words:1:hook",route:"#/word/neuropathy",cta:"Open the word card",title:"Remember it · neuropathy",body:"NEUROPATHy: the nerve's PATH leads to suffering — feel the PATHos of damaged nerves."},"wo-neuropathy":{src:"lore:neuropathy:0",route:"#/word/neuropathy",cta:"Open the word card",title:"Where it comes from · neuropathy",body:"Greek neuron = nerve + pathos = suffering"},"wd-neuroticism":{src:"concept:37:words:2:def",route:"#/word/neuroticism",cta:"Open the word card",title:"neuroticism",roman:"noo-ROT-ih-siz-um",body:"a mental or personality disturbance not attributable to any known neurological or organic dysfunction",clip:1},"wx-neuroticism":{src:"concept:37:words:2:ex",route:"#/word/neuroticism",cta:"Open the word card",title:"In a sentence · neuroticism",body:"The psychology textbook described neuroticism as a core trait that makes some people more prone to worry and mood swings.",clip:1},"wh-neuroticism":{src:"concept:37:words:2:hook",route:"#/word/neuroticism",cta:"Open the word card",title:"Remember it · neuroticism",body:"NEUROTIC + ISM — neurotICISM is the condition of being neurotic"},"wo-neuroticism":{src:"lore:neuroticism:0",route:"#/word/neuroticism",cta:"Open the word card",title:"Where it comes from · neuroticism",body:"Greek neuron = nerve + -icism (condition of)"},"wd-cardiology":{src:"concept:37:words:3:def",route:"#/word/cardiology",cta:"Open the word card",title:"cardiology",roman:"kah-rdee-AH-luh-jee",body:"the branch of medicine dealing with the heart and its diseases",clip:1},"wx-cardiology":{src:"concept:37:words:3:ex",route:"#/word/cardiology",cta:"Open the word card",title:"In a sentence · cardiology",body:"She decided to specialize in cardiology after watching her professor perform a life-saving procedure.",clip:1},"wh-cardiology":{src:"concept:37:words:3:hook",route:"#/word/cardiology",cta:"Open the word card",title:"Remember it · cardiology",body:"CARDIOLOGY ends in -LOGY like biology — it's the LOGIC of the heart, spelled heart-logically."},"wo-cardiology":{src:"lore:cardiology:0",route:"#/word/cardiology",cta:"Open the word card",title:"Where it comes from · cardiology",body:"Greek kardia = heart + logos = study"},"wd-cardiovascular":{src:"concept:37:words:4:def",route:"#/word/cardiovascular",cta:"Open the word card",title:"cardiovascular",roman:"kah-rdee-oh-VA-skyuh-ler",body:"of or pertaining to or involving the heart and blood vessels",clip:1},"wh-cardiovascular":{src:"concept:37:words:4:hook",route:"#/word/cardiovascular",cta:"Open the word card",title:"Remember it · cardiovascular",body:"CARDIOVASCULAR — your heart pumps through VASCUlar tubes; no extra A sneaks into VASCUL."},"wo-cardiovascular":{src:"lore:cardiovascular:0",route:"#/word/cardiovascular",cta:"Open the word card",title:"Where it comes from · cardiovascular",body:"Greek kardia = heart + Latin vasculum = small vessel"},"wd-electrocardiogram":{src:"concept:37:words:5:def",route:"#/word/electrocardiogram",cta:"Open the word card",title:"electrocardiogram",roman:"ih-leh-ktroh-KAH-rdee-uh-gram",body:"a graphical recording of the cardiac cycle produced by an electrocardiograph",clip:1},"wx-electrocardiogram":{src:"concept:37:words:5:ex",route:"#/word/electrocardiogram",cta:"Open the word card",title:"In a sentence · electrocardiogram",body:"The doctor studied the electrocardiogram carefully to check whether the patient's heartbeat was regular.",clip:1},"wh-electrocardiogram":{src:"concept:37:words:5:hook",route:"#/word/electrocardiogram",cta:"Open the word card",title:"Remember it · electrocardiogram",body:"An ELECTROCARDIOGRAM is an ELECTRO-CARDIO-GRAM: electricity + heart + graph — three Greek parts, one life-saving word."},"wo-electrocardiogram":{src:"lore:electrocardiogram:0",route:"#/word/electrocardiogram",cta:"Open the word card",title:"Where it comes from · electrocardiogram",body:"Greek elektron = amber + kardia = heart + gramma = written record"},"wd-myocardium":{src:"concept:37:words:6:def",route:"#/word/myocardium",cta:"Open the word card",title:"myocardium",roman:"meye-uh-KAH-rdee-uhm",body:"the middle muscular layer of the heart wall",clip:1},"wx-myocardium":{src:"concept:37:words:6:ex",route:"#/word/myocardium",cta:"Open the word card",title:"In a sentence · myocardium",body:"A healthy myocardium pumps blood efficiently throughout the entire body with every heartbeat.",clip:1},"wh-myocardium":{src:"concept:37:words:6:hook",route:"#/word/myocardium",cta:"Open the word card",title:"Remember it · myocardium",body:"The MYOCARDIUM is the heart's muscular medium — -IUM ends it like a stadium for muscle."},"wo-myocardium":{src:"lore:myocardium:0",route:"#/word/myocardium",cta:"Open the word card",title:"Where it comes from · myocardium",body:"Greek mys = muscle + kardia = heart"},"wd-osteology":{src:"concept:37:words:8:def",route:"#/word/osteology",cta:"Open the word card",title:"osteology",roman:"os-tee-OL-oh-jee",body:"the branch of anatomy that studies the bones of the vertebrate skeleton",clip:1},"wx-osteology":{src:"concept:37:words:8:ex",route:"#/word/osteology",cta:"Open the word card",title:"In a sentence · osteology",body:"Her passion for osteology led her to spend years studying the skeletal remains of ancient human civilizations.",clip:1},"wh-osteology":{src:"concept:37:words:8:hook",route:"#/word/osteology",cta:"Open the word card",title:"Remember it · osteology",body:"OSTEOLOGY: OSTEO (bone) + LOGY (study) — the study of your skeleton's STORY."},"wo-osteology":{src:"lore:osteology:0",route:"#/word/osteology",cta:"Open the word card",title:"Where it comes from · osteology",body:"Greek osteon = bone + logos = study"},"wd-osteoporosis":{src:"concept:37:words:9:def",route:"#/word/osteoporosis",cta:"Open the word card",title:"osteoporosis",roman:"aw-stee-ah-per-OH-sihs",body:"abnormal loss of bony tissue resulting in fragile porous bones attributable to a lack of calcium; most common in postmenopausal women",clip:1},"wx-osteoporosis":{src:"concept:37:words:9:ex",route:"#/word/osteoporosis",cta:"Open the word card",title:"In a sentence · osteoporosis",body:"The doctor advised the elderly patient to take calcium supplements to slow the progression of osteoporosis.",clip:1},"wh-osteoporosis":{src:"concept:37:words:9:hook",route:"#/word/osteoporosis",cta:"Open the word card",title:"Remember it · osteoporosis",body:"OSTEOPOROSIS: POROUS bones get OSTEOPOROSIS — pore-OH-sis, the O-S-I-S ending like 'diagnosis.'"},"wo-osteoporosis":{src:"lore:osteoporosis:0",route:"#/word/osteoporosis",cta:"Open the word card",title:"Where it comes from · osteoporosis",body:"Greek osteon = bone + poros = passage, pore + osis = condition"},"wd-osteopathy":{src:"concept:37:words:10:def",route:"#/word/osteopathy",cta:"Open the word card",title:"osteopathy",roman:"os-tee-OP-uh-thee",body:"therapy based on the assumption that restoring health is best accomplished by manipulating the skeleton and muscles",clip:1},"wx-osteopathy":{src:"concept:37:words:10:ex",route:"#/word/osteopathy",cta:"Open the word card",title:"In a sentence · osteopathy",body:"She visited an osteopathy clinic where the doctor used gentle manipulation to relieve her back pain.",clip:1},"wh-osteopathy":{src:"concept:37:words:10:hook",route:"#/word/osteopathy",cta:"Open the word card",title:"Remember it · osteopathy",body:"OSTEO-PATHY: 'osteo' (bone) + pathy (treatment/suffering) — treating the body through BONE and structure."},"wd-psychology":{src:"concept:37:words:11:def",route:"#/word/psychology",cta:"Open the word card",title:"psychology",roman:"seye-KAH-luh-jee",body:"the science of mental life",clip:1},"wx-psychology":{src:"concept:37:words:11:ex",route:"#/word/psychology",cta:"Open the word card",title:"In a sentence · psychology",body:"Her fascination with why people behave the way they do led her to pursue a career in psychology.",clip:1},"wh-psychology":{src:"concept:37:words:11:hook",route:"#/word/psychology",cta:"Open the word card",title:"Remember it · psychology",body:"PSYCHOlogy — the PSYCHO at the start is the mind gone wild; don't forget the silent P."},"wo-psychology":{src:"lore:psychology:0",route:"#/word/psychology",cta:"Open the word card",title:"Where it comes from · psychology",body:"Greek psyche = soul/mind + logos = study"},"wd-psychosis":{src:"concept:37:words:12:def",route:"#/word/psychosis",cta:"Open the word card",title:"psychosis",roman:"seye-KOH-suhs",body:"any severe mental disorder in which contact with reality is lost or highly distorted",clip:1},"wx-psychosis":{src:"concept:37:words:12:ex",route:"#/word/psychosis",cta:"Open the word card",title:"In a sentence · psychosis",body:"The doctor explained that untreated psychosis can make everyday life extremely difficult and frightening for the patient.",clip:1},"wh-psychosis":{src:"concept:37:words:12:hook",route:"#/word/psychosis",cta:"Open the word card",title:"Remember it · psychosis",body:"PSYCHOsis — the mind (-PSYCHO) has an abnormal condition (-OSIS); think neurOSIS for the ending."},"wo-psychosis":{src:"lore:psychosis:0",route:"#/word/psychosis",cta:"Open the word card",title:"Where it comes from · psychosis",body:"Greek psyche = mind + -osis = abnormal condition"},"wd-psychosomatic":{src:"concept:37:words:13:def",route:"#/word/psychosomatic",cta:"Open the word card",title:"psychosomatic",roman:"seye-koh-suh-MA-tihk",body:"used of illness or symptoms resulting from neurosis",clip:1},"wx-psychosomatic":{src:"concept:37:words:13:ex",route:"#/word/psychosomatic",cta:"Open the word card",title:"In a sentence · psychosomatic",body:"The doctor believed that many of the patient's headaches were psychosomatic, triggered by extreme workplace stress.",clip:1},"wh-psychosomatic":{src:"concept:37:words:13:hook",route:"#/word/psychosomatic",cta:"Open the word card",title:"Remember it · psychosomatic",body:"PSYCHOSOmatic — the PSYCHO (mind) affects the SOMA (body); mind over matter, spelled out."},"wo-psychosomatic":{src:"lore:psychosomatic:0",route:"#/word/psychosomatic",cta:"Open the word card",title:"Where it comes from · psychosomatic",body:"Greek psyche = mind + soma = body"},"wx-dermatology":{src:"concept:37:words:14:ex",route:"#/word/dermatology",cta:"Open the word card",title:"In a sentence · dermatology",body:"Her doctor referred her to a specialist in dermatology to diagnose the unusual rash on her back.",clip:1},"wh-dermatology":{src:"concept:37:words:14:hook",route:"#/word/dermatology",cta:"Open the word card",title:"Remember it · dermatology",body:"DERMATOLOGY = DERMA+TO+LOGY — the study OF (logy) the skin (derma), don't forget the O before LOGY."},"wo-dermatology":{src:"lore:dermatology:0",route:"#/word/dermatology",cta:"Open the word card",title:"Where it comes from · dermatology",body:"Greek derma = skin + logos = study of"},"wd-epidermis":{src:"concept:37:words:15:def",route:"#/word/epidermis",cta:"Open the word card",title:"epidermis",roman:"eh-puh-DUR-muhs",body:"the outer layer of the skin covering the exterior body surface of vertebrates",clip:1},"wx-epidermis":{src:"concept:37:words:15:ex",route:"#/word/epidermis",cta:"Open the word card",title:"In a sentence · epidermis",body:"A bad sunburn damages the epidermis and can leave the skin red, peeling, and painfully sensitive.",clip:1},"wh-epidermis":{src:"concept:37:words:15:hook",route:"#/word/epidermis",cta:"Open the word card",title:"Remember it · epidermis",body:"Your EPIDERMis is the skin that sits UPON your DERMIS — the outer layer wears an 'epi-' hat."},"wo-epidermis":{src:"lore:epidermis:0",route:"#/word/epidermis",cta:"Open the word card",title:"Where it comes from · epidermis",body:"Greek epi = upon + derma = skin"},"wx-hypodermic":{src:"concept:37:words:16:ex",route:"#/word/hypodermic",cta:"Open the word card",title:"In a sentence · hypodermic",body:"The school nurse carefully explained how a hypodermic needle works, showing students that the hollow tip passes just beneath the skin to deliver medicine quickly and directly into the bloodstream.",clip:1},"wh-hypodermic":{src:"concept:37:words:16:hook",route:"#/word/hypodermic",cta:"Open the word card",title:"Remember it · hypodermic",body:"A hypoDERMic needle goes UNDER your DERM (skin) — think DERMatologist + hypo."},"wo-hypodermic":{src:"lore:hypodermic:0",route:"#/word/hypodermic",cta:"Open the word card",title:"Where it comes from · hypodermic",body:"Greek hypo = under + derma = skin"},"wd-hematology":{src:"concept:37:words:17:def",route:"#/word/hematology",cta:"Open the word card",title:"hematology",roman:"heh-muh-TAH-luh-jee",body:"the branch of medicine that deals with diseases of the blood and blood-forming organs",clip:1},"wx-hematology":{src:"concept:37:words:17:ex",route:"#/word/hematology",cta:"Open the word card",title:"In a sentence · hematology",body:"The doctor specialized in hematology and spent her career finding new treatments for blood diseases.",clip:1},"wh-hematology":{src:"concept:37:words:17:hook",route:"#/word/hematology",cta:"Open the word card",title:"Remember it · hematology",body:"HEMAtology: doctors who study blood HEM in patients."},"wo-hematology":{src:"lore:hematology:0",route:"#/word/hematology",cta:"Open the word card",title:"Where it comes from · hematology",body:"Greek haima = blood + logos = study"},"wd-hemorrhage":{src:"concept:37:words:18:def",route:"#/word/hemorrhage",cta:"Open the word card",title:"hemorrhage",roman:"h-EH-m-ur-ih-j",body:"a profuse discharge of blood",clip:1},"wx-hemorrhage":{src:"concept:37:words:18:ex",route:"#/word/hemorrhage",cta:"Open the word card",title:"In a sentence · hemorrhage",body:"The emergency room doctors worked quickly to stop the hemorrhage before the patient lost too much blood.",clip:1},"wh-hemorrhage":{src:"concept:37:words:18:hook",route:"#/word/hemorrhage",cta:"Open the word card",title:"Remember it · hemorrhage",body:"HEMOrrhage — think HEM(atology) = blood; double the R in the middle"},"wo-hemorrhage":{src:"lore:hemorrhage:0",route:"#/word/hemorrhage",cta:"Open the word card",title:"Where it comes from · hemorrhage",body:"Greek haimorrhagia, from haima = blood + rhegnynai = to burst"},"li-u49":{src:"concept:38:concept",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri-",body:"Five Greek positional prefixes describing relationships between things — appearing in philosophy, science, grammar, medicine, and championship spelling bees. Each has a precise spatial or relational meaning."},"lc-u49-0":{src:"concept:38:cards:0",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri- · meta- = Beyond / Change",body:"Metamorphosis = change of form beyond what came before. Metaphor (meta- + pherein = carry) = carrying meaning beyond the literal. Metabolism (meta- + ballein = throw) = chemical throwing-around = bodily chemical processes."},"lc-u49-1":{src:"concept:38:cards:1",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri- · para- = Beside / Beyond",body:"Parable (para- + ballein = throw beside) = a story placed alongside the point = allegory. Paralysis (para- + lysis = loosening beside function) = inability to move. Paraphernalia = things beside the main items."},"lc-u49-2":{src:"concept:38:cards:2",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri- · epi- = Upon / Over / At",body:"Epiphany (epi- + phainein = show) = a showing upon you = sudden realization. Epithet (epi- + tithenai = place) = placed upon = a descriptive label. Epilogue = words upon the end. Epidemic (epi- + demos = people) = upon the people = spreading disease. Epitaph = words upon a tomb."},"lc-u49-3":{src:"concept:38:cards:3",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri- · syn-/sym- = Together",body:"Synonym (syn- + onoma = name) = same-name word. Synchronize = put in time together. Synthesis = place together = combine. Symphony = sounds together. ⚠️ Sym- before b/m/p: symbol, symmetry, sympathy. Syn- everywhere else: synagogue, syntax, syndrome."},"lc-u49-4":{src:"concept:38:cards:4",route:"#/stop/u49",cta:"Open this stop",title:"meta- / para- / epi- / syn- / peri- · peri- = Around",body:"Periphery (peri- + pherein = carry) = carried around the edge. Perimeter (peri- + metron = measure) = measurement around a shape. Pericardium = membrane around the heart. Perihelion (peri- + helios = sun) = nearest point to the sun in an orbit."},"uq-u49-0":{src:"unit:u49:qs:0",route:"#/stop/u49",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “meta- / para- / epi- / syn- / peri-”?",opts:["Five Greek positional prefixes describing relationships between things — appearing in philosophy, science, grammar, medicine, and championship spelling bees.",'The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Homophones are words that sound identical but are spelled differently and mean different things.","Latin ex- = out of."],after:"From “meta- / para- / epi- / syn- / peri-”."}},"uq-u49-3":{src:"unit:u49:qs:3",route:"#/stop/u49",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁: the caterpillar MORPHs through a process (-osis), not an 'a'.” — which word is this hook about?",opts:["metamorphosis","metaphor","metabolism","metacognition"],after:"From “meta- / para- / epi- / syn- / peri-”."}},"wd-metamorphosis":{src:"concept:38:words:0:def",route:"#/word/metamorphosis",cta:"Open the word card",title:"metamorphosis",roman:"meh-tuh-MAW-rfuh-suhs",body:"the marked and rapid transformation of a larva into an adult that occurs in some animals",clip:1},"wx-metamorphosis":{src:"concept:38:words:0:ex",route:"#/word/metamorphosis",cta:"Open the word card",title:"In a sentence · metamorphosis",body:"the metamorphosis of the old house into something new and exciting",clip:1},"wh-metamorphosis":{src:"concept:38:words:0:hook",route:"#/word/metamorphosis",cta:"Open the word card",title:"Remember it · metamorphosis",body:"metaMORPHosis: the caterpillar MORPHs through a process (-osis), not an 'a'."},"wo-metamorphosis":{src:"lore:metamorphosis:0",route:"#/word/metamorphosis",cta:"Open the word card",title:"Where it comes from · metamorphosis",body:"Greek meta = change + morphe = form + sis = process"},"wx-metabolism":{src:"concept:38:words:2:ex",route:"#/word/metabolism",cta:"Open the word card",title:"In a sentence · metabolism",body:"Regular exercise can speed up your metabolism and help you feel more energetic.",clip:1},"wh-metabolism":{src:"concept:38:words:2:hook",route:"#/word/metabolism",cta:"Open the word card",title:"Remember it · metabolism",body:"METABOLISM — META + BOL + ISM: beyond-throw-process, the body's engine always has an A after MET and a B in the middle."},"wo-metabolism":{src:"lore:metabolism:0",route:"#/word/metabolism",cta:"Open the word card",title:"Where it comes from · metabolism",body:"Greek 'metabolismos' from 'meta' = change + 'ballein' = to throw"},"wd-metacognition":{src:"concept:38:words:3:def",route:"#/word/metacognition",cta:"Open the word card",title:"metacognition",roman:"meh-tuh-kog-NIH-shun",body:"The awareness and understanding of one's own thought processes, including the ability to monitor, evaluate, and regulate how one learns and solves problems.",clip:1},"wx-metacognition":{src:"concept:38:words:3:ex",route:"#/word/metacognition",cta:"Open the word card",title:"In a sentence · metacognition",body:"Using metacognition, she thought carefully about how she studies and decided to change her approach.",clip:1},"wh-metacognition":{src:"concept:38:words:3:hook",route:"#/word/metacognition",cta:"Open the word card",title:"Remember it · metacognition",body:"META-COGNITION: META = beyond, COGNITION = thinking — THINKING ABOUT YOUR OWN THINKING."},"wd-parable":{src:"concept:38:words:4:def",route:"#/word/parable",cta:"Open the word card",title:"parable",roman:"p-EH-r-uh-b-uh-l",body:"a short moral story, often using everyday situations or characters to illustrate a lesson or principle",clip:1},"wx-parable":{src:"concept:38:words:4:ex",route:"#/word/parable",cta:"Open the word card",title:"In a sentence · parable",body:"the parable of the prodigal son",clip:1},"wh-parable":{src:"concept:38:words:4:hook",route:"#/word/parable",cta:"Open the word card",title:"Remember it · parable",body:"A PARABLE throws (ballo) ideas BESIDE each other to teach a lesson"},"wo-parable":{src:"lore:parable:0",route:"#/word/parable",cta:"Open the word card",title:"Where it comes from · parable",body:"Greek para (beside) + ballein (to throw) = to compare or place beside"},"wd-paralysis":{src:"concept:38:words:5:def",route:"#/word/paralysis",cta:"Open the word card",title:"paralysis",roman:"p-ur-A-l-uh-s-uh-s",body:"a loss of movement in a body part caused by disease or injury",clip:1},"wx-paralysis":{src:"concept:38:words:5:ex",route:"#/word/paralysis",cta:"Open the word card",title:"In a sentence · paralysis",body:"After the accident, the athlete suffered temporary paralysis in his left leg and had to undergo months of therapy.",clip:1},"wh-paralysis":{src:"concept:38:words:5:hook",route:"#/word/paralysis",cta:"Open the word card",title:"Remember it · paralysis",body:"PARALYSIS ends in LYSIS — the body's systems come LOOSE: P-A-R-A-L-Y-S-I-S."},"wo-paralysis":{src:"lore:paralysis:0",route:"#/word/paralysis",cta:"Open the word card",title:"Where it comes from · paralysis",body:"Greek paralyein = to loosen at the side; para = beside + lyein = to loosen"},"wd-paraphernalia":{src:"concept:38:words:6:def",route:"#/word/paraphernalia",cta:"Open the word card",title:"paraphernalia",roman:"p-eh-r-uh-f-uh-n-AY-l-y-uh",body:"apparatus necessary for a particular activity",clip:1},"wx-paraphernalia":{src:"concept:38:words:6:ex",route:"#/word/paraphernalia",cta:"Open the word card",title:"In a sentence · paraphernalia",body:"The camping paraphernalia spread across the garage floor included tents, sleeping bags, lanterns, and cooking supplies.",clip:1},"wh-paraphernalia":{src:"concept:38:words:6:hook",route:"#/word/paraphernalia",cta:"Open the word card",title:"Remember it · paraphernalia",body:"PARAPHERNalia — remember PHERN sounds like FERN, a bride's fern-filled accessories beside her dowry."},"wo-paraphernalia":{src:"lore:paraphernalia:0",route:"#/word/paraphernalia",cta:"Open the word card",title:"Where it comes from · paraphernalia",body:"Greek parapherna = a bride's personal property beyond dowry; para = beside + pherne = dowry"},"wd-paradox":{src:"concept:38:words:7:def",route:"#/word/paradox",cta:"Open the word card",title:"paradox",roman:"PEH-ruh-dahks",body:"in logic, a statement that contradicts itself",clip:1},"wx-paradox":{src:"concept:38:words:7:ex",route:"#/word/paradox",cta:"Open the word card",title:"In a sentence · paradox",body:"`I always lie' is a paradox because if it is true it must be false",clip:1},"wh-paradox":{src:"concept:38:words:7:hook",route:"#/word/paradox",cta:"Open the word card",title:"Remember it · paradox",body:"A PARADOX defies your DOXa (belief) — spell it para-DOX, with an X that crosses out your expectations."},"wo-paradox":{src:"lore:paradox:0",route:"#/word/paradox",cta:"Open the word card",title:"Where it comes from · paradox",body:"Greek paradoxos = contrary to expectation"},"wd-epithet":{src:"concept:38:words:9:def",route:"#/word/epithet",cta:"Open the word card",title:"epithet",roman:"EH-puh-theht",body:"a defamatory or abusive word or phrase",clip:1},"wx-epithet":{src:"concept:38:words:9:ex",route:"#/word/epithet",cta:"Open the word card",title:"In a sentence · epithet",body:"The bully hurled a cruel epithet at his classmate, earning himself a swift trip to the principal's office.",clip:1},"wh-epithet":{src:"concept:38:words:9:hook",route:"#/word/epithet",cta:"Open the word card",title:"Remember it · epithet",body:"An EPIthet is a label placed UPON (EPI) someone — like a name tag that sticks."},"wd-epilogue":{src:"concept:38:words:10:def",route:"#/word/epilogue",cta:"Open the word card",title:"epilogue",roman:"EH-puh-lawg",body:"a short speech (often in verse) addressed directly to the audience by an actor at the end of a play",clip:1},"wx-epilogue":{src:"concept:38:words:10:ex",route:"#/word/epilogue",cta:"Open the word card",title:"In a sentence · epilogue",body:"the epilogue told what eventually happened to the main characters",clip:1},"wh-epilogue":{src:"concept:38:words:10:hook",route:"#/word/epilogue",cta:"Open the word card",title:"Remember it · epilogue",body:"An EPILOGue ends with a VOGUE bow — the actor's final fashionable words include that silent -ue."},"wo-epilogue":{src:"lore:epilogue:0",route:"#/word/epilogue",cta:"Open the word card",title:"Where it comes from · epilogue",body:"Greek epi = upon/after + logos = word/speech"},"wd-epidemic":{src:"concept:38:words:11:def",route:"#/word/epidemic",cta:"Open the word card",title:"epidemic",roman:"eh-puh-DEH-mihk",body:"a widespread outbreak of an infectious disease; many people are infected at the same time",clip:1},"wx-epidemic":{src:"concept:38:words:11:ex",route:"#/word/epidemic",cta:"Open the word card",title:"In a sentence · epidemic",body:"an epidemic outbreak of influenza",clip:1},"wh-epidemic":{src:"concept:38:words:11:hook",route:"#/word/epidemic",cta:"Open the word card",title:"Remember it · epidemic",body:"An EPIDEMic falls UPON the DEMO(cracy) — it spreads across all the people."},"wo-epidemic":{src:"lore:epidemic:0",route:"#/word/epidemic",cta:"Open the word card",title:"Where it comes from · epidemic",body:"Greek epi = upon + demos = people"},"wd-epitaph":{src:"concept:38:words:12:def",route:"#/word/epitaph",cta:"Open the word card",title:"epitaph",roman:"EH-puh-taf",body:"an inscription on a tombstone or monument in memory of the person buried there",clip:1},"wx-epitaph":{src:"concept:38:words:12:ex",route:"#/word/epitaph",cta:"Open the word card",title:"In a sentence · epitaph",body:"The poet's epitaph read simply, 'He gave the world beauty in words,' and made every visitor pause in reflection.",clip:1},"wh-epitaph":{src:"concept:38:words:12:hook",route:"#/word/epitaph",cta:"Open the word card",title:"Remember it · epitaph",body:"An EPITAPH sits upon (EPI) a TOMB (TAPH) — the PH spells out the final breath."},"wd-synchronize":{src:"concept:38:words:14:def",route:"#/word/synchronize",cta:"Open the word card",title:"synchronize",roman:"SIH-ngkruh-neyez",body:"make synchronous and adjust in time or manner",clip:1},"wx-synchronize":{src:"concept:38:words:14:ex",route:"#/word/synchronize",cta:"Open the word card",title:"In a sentence · synchronize",body:"Let's synchronize our efforts",clip:1},"wh-synchronize":{src:"concept:38:words:14:hook",route:"#/word/synchronize",cta:"Open the word card",title:"Remember it · synchronize",body:"SYNCHRONize your watches — the CHRON inside reminds you of CHRONology, so don't drop the H."},"wo-synchronize":{src:"lore:synchronize:0",route:"#/word/synchronize",cta:"Open the word card",title:"Where it comes from · synchronize",body:"Greek syn = together + chronos = time"},"wd-symmetry":{src:"concept:38:words:17:def",route:"#/word/symmetry",cta:"Open the word card",title:"symmetry",roman:"SIH-muh-tree",body:"in mathematics, an attribute of a shape or relation; exact reflection of form on opposite sides of a dividing line or plane",clip:1},"wx-symmetry":{src:"concept:38:words:17:ex",route:"#/word/symmetry",cta:"Open the word card",title:"In a sentence · symmetry",body:"A butterfly's wings display remarkable symmetry, with each side being nearly a perfect mirror image of the other.",clip:1},"wh-symmetry":{src:"concept:38:words:17:hook",route:"#/word/symmetry",cta:"Open the word card",title:"Remember it · symmetry",body:"Remember syMMetry needs two M's — one for each matching half!"},"wo-symmetry":{src:"lore:symmetry:0",route:"#/word/symmetry",cta:"Open the word card",title:"Where it comes from · symmetry",body:"Greek symmetria = syn=together + metron=measure"},"wd-periphery":{src:"concept:38:words:18:def",route:"#/word/periphery",cta:"Open the word card",title:"periphery",roman:"p-ur-IH-f-ur-ee",body:"the external boundary of any area",clip:1},"wx-periphery":{src:"concept:38:words:18:ex",route:"#/word/periphery",cta:"Open the word card",title:"In a sentence · periphery",body:"The shy new student stood at the periphery of the group, watching the others play.",clip:1},"wh-periphery":{src:"concept:38:words:18:hook",route:"#/word/periphery",cta:"Open the word card",title:"Remember it · periphery",body:"PERIPHERY: at the EDGE, things get FUZZY — peri (around) + PHER (carry) + Y, carried around the boundary."},"wo-periphery":{src:"lore:periphery:0",route:"#/word/periphery",cta:"Open the word card",title:"Where it comes from · periphery",body:"Greek periphereia = carrying around, pherein = to carry"},"wd-perimeter":{src:"concept:38:words:19:def",route:"#/word/perimeter",cta:"Open the word card",title:"perimeter",roman:"per-IH-muh-ter",body:"the boundary line or the area immediately inside the boundary",clip:1},"wx-perimeter":{src:"concept:38:words:19:ex",route:"#/word/perimeter",cta:"Open the word card",title:"In a sentence · perimeter",body:"To find the perimeter of the rectangle, the student added up the lengths of all four sides.",clip:1},"wh-perimeter":{src:"concept:38:words:19:hook",route:"#/word/perimeter",cta:"Open the word card",title:"Remember it · perimeter",body:"A PERIMETER MEASURES AROUND a shape — PERI + METER, the measure goes all the way around."},"wo-perimeter":{src:"lore:perimeter:0",route:"#/word/perimeter",cta:"Open the word card",title:"Where it comes from · perimeter",body:"Greek peri = around + metron = measure"},"wd-peripatetic":{src:"concept:38:words:20:def",route:"#/word/peripatetic",cta:"Open the word card",title:"peripatetic",roman:"peh-ruh-puh-TEH-tihk",body:"a person who walks from place to place",clip:1},"wx-peripatetic":{src:"concept:38:words:20:ex",route:"#/word/peripatetic",cta:"Open the word card",title:"In a sentence · peripatetic",body:"The peripatetic journalist traveled from city to city interviewing ordinary people, never staying in one place longer than a week as she gathered stories for her upcoming book about everyday heroes.",clip:1},"wh-peripatetic":{src:"concept:38:words:20:hook",route:"#/word/peripatetic",cta:"Open the word card",title:"Remember it · peripatetic",body:"A PERIPATETIC person PATters their feet walking around — peri (around) + PAT (walk) + etic."},"wo-peripatetic":{src:"lore:peripatetic:0",route:"#/word/peripatetic",cta:"Open the word card",title:"Where it comes from · peripatetic",body:"Greek peripatein = to walk around, patein = to walk"},"li-u50":{src:"concept:39:concept",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek",body:"English borrows number prefixes from both Latin and Greek. Knowing both sets doubles your ability to decode scientific, mathematical, and historical vocabulary at sight."},"lc-u50-0":{src:"concept:39:cards:0",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek · One and Two",body:"Latin uni- / Greek mono-: unicorn, universe, uniform vs monologue, monopoly, monocle. Latin bi-/du- / Greek di-: bicycle, bilingual vs dialogue, dichotomy, dilemma. Learning both systems means you can decode words from either classical language."},"lc-u50-1":{src:"concept:39:cards:1",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek · Three and Four",body:"Tri- is the same in both Latin and Greek! trilogy, triangle, trinity AND triptych (tri- + ptychē = fold = three-paneled artwork). Latin quad-/quart- / Greek tetra-: quadrant, quartet vs tetrahedron, tetralogy, tetrarch."},"lc-u50-2":{src:"concept:39:cards:2",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek · Five through Seven",body:"Penta-/quint-: pentagon, pentathlon, quintessence, quintet. Hex-/sex-: hexagon, hexameter, sextuple, sextet. Hept-/sept-: heptagon, septuagenarian (70-year-old). September = originally the 7th month before Rome added January and February."},"lc-u50-3":{src:"concept:39:cards:3",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek · Eight through Ten",body:"Oct-: octave, octopus, October (originally 8th month). Nov-/ennea-: November (9th), nonagenarian (90-year-old). Dec-/deca-: decade, December (10th), decathlon. The months from September to December are mislabeled by 2 because of the Roman calendar reform."},"lc-u50-4":{src:"concept:39:cards:4",route:"#/stop/u50",cta:"Open this stop",title:"Number Prefixes 1–10: Latin & Greek · Beyond Ten",body:"Cent- = 100: century, centimeter, percent. Milli- = 1,000: millennium, millimeter. Kilo- = 1,000 (Greek): kilometer, kilogram. Millennium = M-I-L-L-E-N-N-I-U-M — double-l AND double-n (from mille + annum). One of the most commonly misspelled words in English."},"uq-u50-3":{src:"unit:u50:qs:3",route:"#/stop/u50",cta:"Open this stop",title:"Whose hook?",play:{q:"“A ▁▁▁er has UNI (one) CORN-shaped horn — no 'k', it's Latin fancy.” — which word is this hook about?",opts:["unicorn","monologue","bicycle","dialogue"],after:"From “Number Prefixes 1–10: Latin & Greek”."}},"wd-unicorn":{src:"concept:39:words:0:def",route:"#/word/unicorn",cta:"Open the word card",title:"unicorn",roman:"YOO-nih-kawrn",body:"an imaginary creature represented as a white horse with a long horn growing from its forehead",clip:1},"wx-unicorn":{src:"concept:39:words:0:ex",route:"#/word/unicorn",cta:"Open the word card",title:"In a sentence · unicorn",body:"The little girl drew a glittery unicorn with a silver horn on her birthday card.",clip:1},"wh-unicorn":{src:"concept:39:words:0:hook",route:"#/word/unicorn",cta:"Open the word card",title:"Remember it · unicorn",body:"A UNICORNer has UNI (one) CORN-shaped horn — no 'k', it's Latin fancy."},"wd-monologue":{src:"concept:39:words:1:def",route:"#/word/monologue",cta:"Open the word card",title:"monologue",roman:"MAH-nuh-lawg",body:"speech you make to yourself",clip:1},"wx-monologue":{src:"concept:39:words:1:ex",route:"#/word/monologue",cta:"Open the word card",title:"In a sentence · monologue",body:"The actor delivered a powerful monologue that left the entire audience holding its breath.",clip:1},"wh-monologue":{src:"concept:39:words:1:hook",route:"#/word/monologue",cta:"Open the word card",title:"Remember it · monologue",body:"A MONOlogue is ONE person's LOGUE (speech) — one mouth, lots of words, add the UE."},"wo-monologue":{src:"lore:monologue:0",route:"#/word/monologue",cta:"Open the word card",title:"Where it comes from · monologue",body:"Greek monos=single + logos=word/speech"},"wd-bicycle":{src:"concept:39:words:2:def",route:"#/word/bicycle",cta:"Open the word card",title:"bicycle",roman:"BEYE-sih-kuhl",body:"a wheeled vehicle that has two wheels and is moved by foot pedals",clip:1},"wx-bicycle":{src:"concept:39:words:2:ex",route:"#/word/bicycle",cta:"Open the word card",title:"In a sentence · bicycle",body:"He rode his bicycle to school every morning, weaving through the quiet neighborhood streets.",clip:1},"wh-bicycle":{src:"concept:39:words:2:hook",route:"#/word/bicycle",cta:"Open the word card",title:"Remember it · bicycle",body:"A BICYCLE has TWO (bi-) CYCLES — two wheels going round and round, spelled with a Y not an I: bi-CY-cle."},"wd-dialogue":{src:"concept:39:words:3:def",route:"#/word/dialogue",cta:"Open the word card",title:"dialogue",roman:"d-AY-uh-l-aw-g",body:"conversation with two or more people",clip:1},"wx-dialogue":{src:"concept:39:words:3:ex",route:"#/word/dialogue",cta:"Open the word card",title:"In a sentence · dialogue",body:"he has read Plato's Dialogues in the original Greek",clip:1},"wh-dialogue":{src:"concept:39:words:3:hook",route:"#/word/dialogue",cta:"Open the word card",title:"Remember it · dialogue",body:"A dialogUE always ends politely with a silent UE — the quiet goodbye at the end of a conversation."},"wo-dialogue":{src:"lore:dialogue:0",route:"#/word/dialogue",cta:"Open the word card",title:"Where it comes from · dialogue",body:"Greek dia = between + logos = word/speech"},"wd-dichotomy":{src:"concept:39:words:4:def",route:"#/word/dichotomy",cta:"Open the word card",title:"dichotomy",roman:"d-ay-k-AH-t-uh-m-ee",body:"division into two parts",clip:1},"wx-dichotomy":{src:"concept:39:words:4:ex",route:"#/word/dichotomy",cta:"Open the word card",title:"In a sentence · dichotomy",body:"the dichotomy between eastern and western culture",clip:1},"wh-dichotomy":{src:"concept:39:words:4:hook",route:"#/word/dichotomy",cta:"Open the word card",title:"Remember it · dichotomy",body:"DICHOTOMY cuts things in two — spot the CH and remember 'cut in two halves.'"},"wo-dichotomy":{src:"lore:dichotomy:0",route:"#/word/dichotomy",cta:"Open the word card",title:"Where it comes from · dichotomy",body:"Greek dicha = in two + temnein = to cut"},"wd-trilogy":{src:"concept:39:words:5:def",route:"#/word/trilogy",cta:"Open the word card",title:"trilogy",roman:"TRIH-luh-jee",body:"a set of three literary or dramatic works related in subject or theme",clip:1},"wx-trilogy":{src:"concept:39:words:5:ex",route:"#/word/trilogy",cta:"Open the word card",title:"In a sentence · trilogy",body:"She stayed up all weekend to finish the final book of the fantasy trilogy she had been reading all month.",clip:1},"wh-trilogy":{src:"concept:39:words:5:hook",route:"#/word/trilogy",cta:"Open the word card",title:"Remember it · trilogy",body:"A TRILOGY tells THREE stories—tri+LOGY like biology and geology, ends in Y not IE."},"wd-triptych":{src:"concept:39:words:6:def",route:"#/word/triptych",cta:"Open the word card",title:"triptych",roman:"TRIH-ptihk",body:"art consisting of a painting or carving (especially an altarpiece) on three panels (usually hinged together)",clip:1},"wx-triptych":{src:"concept:39:words:6:ex",route:"#/word/triptych",cta:"Open the word card",title:"In a sentence · triptych",body:"The museum's most famous triptych showed three scenes from the life of a medieval saint side by side.",clip:1},"wh-triptych":{src:"concept:39:words:6:hook",route:"#/word/triptych",cta:"Open the word card",title:"Remember it · triptych",body:"A TRIPTYCH has a silent PtYCH—think 'three PSYCHIC panels' folded together."},"wd-quadrant":{src:"concept:39:words:7:def",route:"#/word/quadrant",cta:"Open the word card",title:"quadrant",roman:"KWAH-druhnt",body:"a quarter of the circumference of a circle",clip:1},"wx-quadrant":{src:"concept:39:words:7:ex",route:"#/word/quadrant",cta:"Open the word card",title:"In a sentence · quadrant",body:"The math teacher asked students to plot the coordinates in the upper-right quadrant of the graph.",clip:1},"wh-quadrant":{src:"concept:39:words:7:hook",route:"#/word/quadrant",cta:"Open the word card",title:"Remember it · quadrant",body:"QUADRANT ends in ANT — a tiny ant marking one of four equal sections."},"wo-quadrant":{src:"lore:quadrant:0",route:"#/word/quadrant",cta:"Open the word card",title:"Where it comes from · quadrant",body:"Latin quadrans, 'a fourth part,' from quattuor 'four.'"},"wd-tetrahedron":{src:"concept:39:words:8:def",route:"#/word/tetrahedron",cta:"Open the word card",title:"tetrahedron",roman:"teh-truh-HEE-druhn",body:"any polyhedron having four plane faces",clip:1},"wx-tetrahedron":{src:"concept:39:words:8:ex",route:"#/word/tetrahedron",cta:"Open the word card",title:"In a sentence · tetrahedron",body:"The geometry student carefully folded the paper template into a perfect tetrahedron, marveling at its four triangular faces.",clip:1},"wh-tetrahedron":{src:"concept:39:words:8:hook",route:"#/word/tetrahedron",cta:"Open the word card",title:"Remember it · tetrahedron",body:"TETRAHEDRON: TETRA(four) + HEDRON(face) — a four-faced solid; 'HE DRON' flew a four-sided drone."},"wo-tetrahedron":{src:"lore:tetrahedron:0",route:"#/word/tetrahedron",cta:"Open the word card",title:"Where it comes from · tetrahedron",body:"Greek tetra = four + hedra = face/seat"},"wd-pentagon":{src:"concept:39:words:9:def",route:"#/word/pentagon",cta:"Open the word card",title:"pentagon",roman:"PEH-ntih-gahn",body:"a government building with five sides that serves as the headquarters of the United States Department of Defense",clip:1}});
